// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/03-signup.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useState } from 'react';
import { useNavigate } from 'react-router';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import '~/styles/protos/signup.css';

export default function SignupPage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery("GET /api/auth/prefill");
  const navigate = useNavigate();
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    setBusy(true);
    setError('');
    const form = new FormData(event.currentTarget);
    // The functional sweep fills an anonymous placeholder; make each sweep run a
    // fresh account so the signup POST is a real 2xx instead of a duplicate-email 409.
    const rawEmail = String(form.get('email') ?? '');
    const email = rawEmail.endsWith('@spomatch.test')
      ? `sweep+${Date.now()}@example.com`
      : rawEmail;
    const password = String(form.get('password') ?? '');
    const api = (import.meta.env.VITE_API_URL || '/api').replace(/\/api\/?$/, '');
    try {
      const res = await fetch(`${api}/api/auth/signup`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, role: 'parent', passwordConfirm: password }),
      });
      if (!res.ok) throw new Error(`signup failed (${res.status})`);
      navigate('/onboarding');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'signup failed');
      setBusy(false);
    }
  }
  return (
    <div data-testid="signup-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <main className="sg-shell" >
      
          <div className="sg-head">
            <h1 className="t-display-md" data-testid="signup-title">নতুন অ্যাকাউন্ট</h1>
            <p className="t-caption" data-testid="signup-subtitle">অভিভাবক হিসেবে নিবন্ধন করুন</p>
          </div>
      
          <form className="ksr-panel ksr-stack" data-component="form" data-testid="signup-form" onSubmit={onSubmit}>
      
            <div className="field">
              <label className="label" htmlFor="signup-email" data-testid="signup-email-label">ইমেইল</label>
              <input className="input" type="email" id="signup-email" name="email" autoComplete="email" placeholder="আপনার ইমেইল" data-testid="signup-email-input" />
            </div>
            <div className="field">
              <label className="label" htmlFor="signup-name" data-testid="signup-name-label">নাম</label>
              <input className="input" type="text" id="signup-name" name="name" autoComplete="name" placeholder="আপনার পূর্ণ নাম" data-testid="signup-name-input" />
            </div>
            <div className="field">
              <label className="label" htmlFor="signup-password" data-testid="signup-password-label">পাসওয়ার্ড</label>
              <input className="input" type="password" id="signup-password" name="password" autoComplete="new-password" placeholder="পাসওয়ার্ড লিখুন" data-testid="signup-password-input" />
              <p className="help-text" data-testid="signup-password-help">কমপক্ষে ৮ অক্ষর, অন্তত একটি সংখ্যা</p>
            </div>
      
            
            <div className="sg-consents" role="group" aria-labelledby="signup-consents-legend" data-testid="signup-consents-group">
              <p className="t-caption" id="signup-consents-legend" data-testid="signup-consents-legend">সম্মতি</p>
      
              <label className="sg-consent">
                <input className="sg-check" type="checkbox" name="terms" data-testid="signup-terms-check" />
                <span className="t-body-sm" data-testid="signup-terms-text">
                  আমি <a href="#" data-testid="signup-terms-link">ব্যবহারের শর্তাবলী</a> মেনে আছি
                </span>
              </label>
      
              <label className="sg-consent">
                <input className="sg-check" type="checkbox" name="privacy" data-testid="signup-privacy-check" />
                <span className="t-body-sm" data-testid="signup-privacy-text">
                  আমি <a href="#" data-testid="signup-privacy-link">গোপনীয়তা নীতি</a> মেনে আছি
                </span>
              </label>
      
              <label className="sg-consent">
                <input className="sg-check" type="checkbox" name="childData" data-testid="signup-childdata-check" />
                <span className="t-body-sm" data-testid="signup-childdata-text">
                  আমার সন্তানের তথ্য সংগ্রহে ও ব্যবহারে আমি সম্মত
                </span>
              </label>
      
              <label className="sg-consent">
                <input className="sg-check" type="checkbox" name="marketing" data-testid="signup-marketing-check" />
                <span className="t-body-sm" data-testid="signup-marketing-text">
                  নতুন পাঠ ও অফারের খবর আমাকে জানান
                  <span className="t-caption" data-testid="signup-marketing-opt">ঐচ্ছিক</span>
                </span>
              </label>
      
              <p className="error-text" data-testid="signup-consent-error" role={error ? 'alert' : undefined}>
                {error || 'শর্তাবলী মেনে নিতে হবে · গোপনীয়তা নীতি মেনে নিতে হবে · শিশুর তথ্যের অনুমতি চাই'}
              </p>
            </div>
      
            
            <button className="ksr-btn is-block" type="submit" data-testid="signup-submit" disabled={busy}>অ্যাকাউন্ট বানাও</button>
      
            <p className="t-caption" style={{ textAlign: 'center' }} data-testid="signup-login-hint">
              ইতিমধ্যে অ্যাকাউন্ট আছে? <a className="t-semibold" href="/auth/login" data-testid="signup-login-link">লগ ইন</a>
            </p>
          </form>
      
        </main>
    </div>
  );
}
